 const ensure=()=>{if(dialog)return; dialog=document.createElement('div');dialog.className='page-media-dialog';dialog.hidden=true;dialog.innerHTML=`<button class="page-media-backdrop" type="button" aria-label="Close media library"></button><section role="dialog" aria-modal="true" aria-labelledby="page-media-title"><header><div><p>MEDIA LIBRARY</p><h2 id="page-media-title">Choose media</h2><span>Select an existing file or upload a new one.</span></div><button type="button" data-media-close aria-label="Close">×</button></header><div class="page-media-upload"><label class="page-media-upload-button">Upload media<input type="file" data-media-upload multiple accept="image/*,video/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt"></label><small data-media-upload-status></small></div><div class="page-media-list" data-media-list></div></section>`;document.body.append(dialog);dialog.querySelector('[data-media-close]').onclick=close;dialog.querySelector('.page-media-backdrop').onclick=close;dialog.querySelector('[data-media-upload]').onchange=async(event)=>{const input=event.target,status=dialog.querySelector('[data-media-upload-status]');if(!input.files.length)return;status.textContent='Uploading…';const body=new FormData();[...input.files].forEach(file=>body.append('file[]',file));try{const response=await fetch('{{ route('staff.media-library.upload') }}',{method:'POST',body,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''}});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'Upload failed.');(payload.assets||[]).forEach(asset=>{[...new Set([activeSelect,...document.querySelectorAll('select[data-media],select[data-media-for]')])].filter(Boolean).forEach(select=>{const option=document.createElement('option');option.value=asset.url;option.textContent=asset.title;option.dataset.mediaType=asset.kind||'file';select.insertBefore(option, select.options[1] || null);});});status.textContent='Uploaded. Choose the new file below.';render();}catch(error){status.textContent=error.message;}}};
 const render=()=>{if(!dialog||!activeSelect)return;const list=dialog.querySelector('[data-media-list]');list.replaceChildren();[...activeSelect.options].filter(option=>option.value).forEach(option=>{const button=document.createElement('button');button.type='button';button.className='page-media-option';button.style.cssText='appearance:none;-webkit-appearance:none;background:var(--surface-muted) !important;background-color:var(--surface-muted) !important;border:1px solid var(--line) !important;color:var(--ink) !important;box-shadow:none !important;';const type=option.dataset.mediaType||"file";const visual=type==="image"?`<img src="${option.value}" alt="" loading="lazy">`:type==="video"?`<video src="${option.value}" muted preload="metadata"></video>`:`<span class="page-media-file-tile">${type.toUpperCase()}</span>`;button.innerHTML=`<span class="page-media-thumb">${visual}</span><strong>${option.textContent}</strong><span>${type}</span>`;button.onclick=()=>{activeSelect.value=option.value;activeSelect.dispatchEvent(new Event('change',{bubbles:true}));const field=activeSelect.dataset.mediaFor||'url';const input=editor.querySelector('[data-field='+JSON.stringify(field)+']');if(input){input.value=option.value;input.dispatchEvent(new Event('input',{bubbles:true}));}close();};list.append(button);});};
 const open=(select)=>{ensure();activeSelect=select;render();dialog.hidden=false;};
 const wire=()=>{editor.querySelectorAll('select[data-media],select[data-media-for]').forEach(select=>{const wrapper=select.closest('.enhanced-select');if(wrapper&&!wrapper.dataset.mediaPicker){wrapper.dataset.mediaPicker='true';wrapper.classList.add('page-media-select');const trigger=document.createElement('button');trigger.type='button';trigger.className='page-media-picker-trigger';trigger.style.cssText='appearance:none;-webkit-appearance:none;background:#fafafa !important;background-color:#fafafa !important;border:1px solid #d4d4d8 !important;color:#27272a !important;box-shadow:none !important;';trigger.textContent=select.options[select.selectedIndex]?.textContent||'Choose from media library';trigger.onclick=()=>open(select);wrapper.replaceChildren(select,trigger);select.addEventListener('change',()=>{trigger.textContent=select.options[select.selectedIndex]?.textContent||'Choose from media library';});}else if(!wrapper&&!select.dataset.mediaPicker){select.dataset.mediaPicker='true';const trigger=document.createElement('button');trigger.type='button';trigger.className='page-media-picker-trigger';trigger.style.cssText='appearance:none;-webkit-appearance:none;background:#fafafa !important;background-color:#fafafa !important;border:1px solid #d4d4d8 !important;color:#27272a !important;box-shadow:none !important;';trigger.textContent=select.options[select.selectedIndex]?.textContent||'Choose from media library';trigger.onclick=()=>open(select);select.replaceWith(trigger);}});};
 wire();new MutationObserver(wire).observe(editor,{childList:true,subtree:true});
})();</script>

<script>
(()=>{
 const editor=document.querySelector('[data-page-block-editor]');if(!editor)return;
 const inspector=editor.querySelector('[data-inspector]');if(!inspector)return;
 const enhance=()=>{if(inspector.querySelector('[data-object-tabs]'))return;const selected=inspector.querySelector('.page-inspector-selected');if(!selected)return;const actions=inspector.querySelector('.page-inspector-actions');const tabs=document.createElement('div');tabs.className='page-object-tabs';tabs.dataset.objectTabs='true';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Selected object settings');const content=document.createElement('section');content.className='page-object-tab-panel is-active';content.dataset.objectPanel='content';content.setAttribute('role','tabpanel');const style=document.createElement('section');style.className='page-object-tab-panel';style.dataset.objectPanel='style';style.setAttribute('role','tabpanel');style.hidden=true;style.innerHTML='<p class="page-object-tab-empty">Style controls for this object will appear here.</p>';const advanced=document.createElement('section');advanced.className='page-object-tab-panel';advanced.dataset.objectPanel='advanced';advanced.setAttribute('role','tabpanel');advanced.hidden=true;advanced.innerHTML='<p class="page-object-tab-empty">Responsive and advanced controls will appear here.</p>';['Content','Style','Advanced'].forEach((label,index)=>{const button=document.createElement('button');button.type='button';button.textContent=label;button.dataset.objectTab=['content','style','advanced'][index];button.setAttribute('role','tab');button.setAttribute('aria-selected',index===0?'true':'false');button.onclick=(event)=>{event.stopPropagation();tabs.querySelectorAll('[data-object-tab]').forEach(x=>x.classList.toggle('is-active',x===button));tabs.querySelectorAll('[data-object-panel]').forEach(x=>{x.hidden=x.dataset.objectPanel!==button.dataset.objectTab});tabs.querySelectorAll('[data-object-tab]').forEach(x=>x.setAttribute('aria-selected',x===button?'true':'false'));};tabs.append(button)});[...inspector.children].filter(node=>node!==actions).forEach(node=>content.append(node));inspector.replaceChildren(tabs,content,style,advanced);if(actions)inspector.append(actions)};new MutationObserver(()=>queueMicrotask(enhance)).observe(inspector,{childList:true});enhance();})();
</script>
<script>
document.addEventListener('click',(event)=>{const button=event.target.closest('[data-object-tab]');if(!button)return;const tabs=button.closest('[data-object-tabs]');if(!tabs)return;const key=button.dataset.objectTab;tabs.querySelectorAll('[data-object-tab]').forEach(x=>x.setAttribute('aria-selected',x===button?'true':'false'));const inspector=tabs.parentElement;inspector.querySelectorAll('[data-object-panel]').forEach(panel=>{const active=panel.dataset.objectPanel===key;panel.hidden=!active;panel.classList.toggle('is-active',active);panel.style.display=active?'block':'none';});},{capture:true});
</script>
<script>
(()=>{const root=document.querySelector('[data-page-block-editor]');if(!root)return;const inspect=()=>{const style=root.querySelector('[data-object-panel="style"]');const advanced=root.querySelector('[data-object-panel="advanced"]');if(style&&style.querySelector('.page-object-tab-empty'))style.innerHTML='<div class="page-object-control-grid"><label>Background color<input type="color" data-field="background_color" value="#ffffff"></label><label>Text alignment<select data-field="text_align"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label><label>Border color<input type="color" data-field="border_color" value="#d4d4d8"></label><label>Border width<input type="number" min="0" max="12" data-field="border_width" value="0"></label><label>Corner radius<input type="number" min="0" max="48" data-field="border_radius" value="0"></label><label>Padding<input data-field="padding_custom" placeholder="24px"></label><label>Margin<input data-field="margin_custom" placeholder="0 auto"></label></div>';if(advanced&&advanced.querySelector('.page-object-tab-empty'))advanced.innerHTML='<div class="page-object-control-grid"><label>Desktop visibility<select data-field="desktop_visibility"><option value="visible">Visible</option><option value="hidden">Hidden</option></select></label><label>Tablet visibility<select data-field="tablet_visibility"><option value="visible">Visible</option><option value="hidden">Hidden</option></select></label><label>Mobile visibility<select data-field="mobile_visibility"><option value="visible">Visible</option><option value="hidden">Hidden</option></select></label><label>CSS class<input data-field="custom_class" placeholder="Optional"></label></div>';};inspect();new MutationObserver(inspect).observe(root,{childList:true,subtree:true});})();
</script><script>
(()=>{const editor=document.querySelector('[data-page-block-editor]');if(!editor)return;const canvas=editor.querySelector('[data-canvas]');const inspector=editor.querySelector('[data-inspector]');const decorate=()=>{canvas.querySelectorAll('[data-index]').forEach((section,index)=>{section.dataset.editorObject='section';section.querySelectorAll('.page-canvas-block-content').forEach(el=>{el.dataset.editorObject='element';});section.querySelectorAll('.page-canvas-columns>div').forEach((column,columnIndex)=>{column.dataset.editorObject='column';column.dataset.columnIndex=columnIndex;column.setAttribute('tabindex','0');column.setAttribute('aria-label','Edit column '+(columnIndex+1));});});};const selectObject=(kind,node)=>{canvas.querySelectorAll('[data-editor-object].is-object-selected').forEach(x=>x.classList.remove('is-object-selected'));node.classList.add('is-object-selected');if(inspector){inspector.dataset.selectedObject=kind;const label=inspector.querySelector('.page-inspector-selected span');if(label)label.textContent=(kind[0].toUpperCase()+kind.slice(1))+' settings';}};canvas.addEventListener('click',event=>{const column=event.target.closest('[data-editor-object="column"]');if(column){event.stopPropagation();selectObject('column',column);return;}const content=event.target.closest('[data-editor-object="element"]');if(content){selectObject('element',content);return;}const section=event.target.closest('[data-editor-object="section"]');if(section)selectObject('section',section);});canvas.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-editor-object="column"]')){event.preventDefault();selectObject('column',event.target);}});decorate();new MutationObserver(decorate).observe(canvas,{childList:true,subtree:true});})();
</script><script>
(()=>{const editor=document.querySelector('[data-page-block-editor]');if(!editor)return;const inspector=editor.querySelector('[data-inspector]');const panel=()=>inspector.querySelector('[data-object-panel="style"]');let last='';const sync=()=>{const p=panel(),kind=inspector.dataset.selectedObject||'section';if(!p)return;const key=kind+':'+(editor.querySelector('.is-object-selected')?.dataset.columnIndex||'0');if(key===last)return;last=key;const title=kind==='column'?'Column layout':'Section layout';p.insertAdjacentHTML('afterbegin','<div class="page-object-layout-heading"><strong>'+title+'</strong><small>Adjust this layout object without changing its content.</small></div>');};sync();setInterval(sync,250);})();
