(()=>{const root=document.querySelector('[data-page-block-editor]');if(!root)return;const inspector=root.querySelector('[data-inspector]');let seen='';const add=()=>{const panel=inspector.querySelector('[data-object-panel="style"]');const api=window.oneMinistryPageEditor;if(!panel||!api)return;const kind=inspector.dataset.selectedObject||'section';const object=root.querySelector('.is-object-selected');const key=kind+':'+(object?.dataset.columnIndex||'0');if(key===seen&&panel.querySelector('[data-layout-control]'))return;seen=key;panel.querySelectorAll('[data-layout-control]').forEach(x=>x.remove());const wrap=document.createElement('div');wrap.className='page-object-layout-controls';wrap.dataset.layoutControl='true';wrap.innerHTML='<strong>Layout</strong><label>Content width<select data-layout-field="content_width"><option value="full">Full width</option><option value="wide">Wide</option><option value="standard">Standard</option><option value="narrow">Narrow</option></select></label><label>Column gap<select data-layout-field="column_gap"><option value="small">Small</option><option value="regular">Regular</option><option value="large">Large</option></select></label><label>Horizontal alignment<select data-layout-field="horizontal_align"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option><option value="stretch">Stretch</option></select></label><label>Vertical alignment<select data-layout-field="vertical_align"><option value="top">Top</option><option value="center">Center</option><option value="bottom">Bottom</option><option value="stretch">Stretch</option></select></label><label>Mobile behavior<select data-layout-field="mobile_behavior"><option value="stack">Stack columns</option><option value="inline">Keep inline</option><option value="reverse">Reverse order</option></select></label>';wrap.querySelectorAll('[data-layout-field]').forEach(field=>field.addEventListener('change',()=>{const index=api.selected;api.updateBlock(index,{[field.dataset.layoutField]:field.value});}));panel.append(wrap);};add();setInterval(add,250);})();
</script><script>
(()=>{const form=document.querySelector('[data-page-block-editor]');const inspector=form?.querySelector('[data-inspector]');const canvas=form?.querySelector('[data-canvas]');if(!form||!inspector||!canvas)return;const activate=(key)=>{inspector.querySelectorAll('[data-object-tab]').forEach(button=>{const active=button.dataset.objectTab===key;button.classList.toggle('is-active',active);button.setAttribute('aria-selected',active?'true':'false');});inspector.querySelectorAll('[data-object-panel]').forEach(panel=>{const active=panel.dataset.objectPanel===key;panel.hidden=!active;panel.style.display=active?'block':'none';});};const placeAssistant=()=>{const content=inspector.querySelector('[data-object-panel="content"]');const actions=inspector.querySelector('.page-inspector-actions');const selected=canvas.querySelector('.page-canvas-block.is-selected');if(!content||!actions||!selected)return;let assistant=inspector.querySelector('[data-section-ai-controls]');if(!assistant){assistant=document.createElement('section');assistant.className='page-section-ai';assistant.dataset.sectionAiControls='';assistant.innerHTML='<strong>Edit this section with AI</strong><p>The assistant receives the full page for context and proposes changes to this selected section only.</p><textarea data-section-ai-instruction rows="3" maxlength="1500" placeholder="Describe what you want changed in this section…"></textarea><button type="button" class="button" data-section-ai-ask disabled>Suggest changes</button><p class="page-section-ai-status" role="status">AI editing is unavailable until an administrator verifies a model route in AI model settings.</p>';}content.append(assistant);assistant.hidden=false;};const sync=()=>{const panels=[...inspector.querySelectorAll('[data-object-panel]')];if(!panels.length)return;const active=inspector.querySelector('[data-object-tab][aria-selected="true"]')?.dataset.objectTab||'content';activate(active);placeAssistant();};inspector.addEventListener('click',event=>{const button=event.target.closest('[data-object-tab]');if(!button)return;event.preventDefault();activate(button.dataset.objectTab);});new MutationObserver(sync).observe(inspector,{childList:true,subtree:true});sync();})();
</script><script>
(()=>{const inspector=document.querySelector('[data-page-block-editor] [data-inspector]');if(!inspector)return;const ensure=()=>{const content=inspector.querySelector('[data-object-panel="content"]');if(!content||content.querySelector('[data-section-ai-controls]'))return;const section=document.createElement('section');section.className='page-section-ai';section.dataset.sectionAiControls='';section.innerHTML='<strong>Edit this section with AI</strong><p>The assistant receives the full page for context and proposes changes to this selected section only.</p><textarea data-section-ai-instruction rows="3" maxlength="1500" placeholder="Describe what you want changed in this section…"></textarea><button type="button" class="button" data-section-ai-ask disabled>Suggest changes</button><p class="page-section-ai-status" role="status">AI editing is unavailable until an administrator verifies a model route in AI model settings.</p>';content.append(section);};new MutationObserver(ensure).observe(inspector,{childList:true,subtree:true});ensure();})();
